CREATE OR REPLACE FUNCTION public.link_evaluation_reference() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.reference_value IS NULL THEN NEW.reference_id:=NULL; ELSIF TG_OP='INSERT' OR NEW.model IS DISTINCT FROM OLD.model OR NEW.storage IS DISTINCT FROM OLD.storage OR NEW.reference_value IS DISTINCT FROM OLD.reference_value THEN SELECT id INTO NEW.reference_id FROM public.evaluation_prices WHERE store_id=NEW.store_id AND NOT archived AND lower(model)=lower(NEW.model) AND storage=NEW.storage; END IF; RETURN NEW; END $$;
CREATE TRIGGER update_evaluation_reference BEFORE UPDATE OF model,storage,reference_value ON public.evaluations FOR EACH ROW EXECUTE FUNCTION public.link_evaluation_reference();